package ru.neverland.townyarmy.tactics;
import java.util.*;import java.math.BigDecimal;
import org.bukkit.Material;import org.bukkit.configuration.ConfigurationSection;
import ru.neverland.townyarmy.ArmyModel;
import static ru.neverland.townyarmy.tactics.TacticsBook.*;
public record TacticsSettings(boolean enabled,int kitsPerDay,long kitCooldown,long orderDuration,double arrivalRadius,int activeOrders,Map<Role,Loadout> loadouts){
 public record Loadout(Map<String,Long> cost,Map<String,Integer> items){public Loadout{cost=ArmyModel.stock(cost);items=Map.copyOf(items);if(cost.isEmpty()||items.isEmpty()||items.size()>12||items.values().stream().anyMatch(n->n==null||n<1||n>64))throw new IllegalArgumentException("Неверный комплект снаряжения");for(String id:items.keySet())if(!id.equals("SPLASH_POTION_HEALING")&&(Material.getMaterial(id)==null||Set.of("AIR","CAVE_AIR","VOID_AIR").contains(id)))throw new IllegalArgumentException("Неизвестный предмет комплекта: "+id);}}
 public TacticsSettings{loadouts=Map.copyOf(loadouts);if(kitsPerDay<1||kitsPerDay>10||kitCooldown<60000||kitCooldown>DAY||orderDuration<60000||orderDuration>DAY||!Double.isFinite(arrivalRadius)||arrivalRadius<2||arrivalRadius>64||activeOrders<1||activeOrders>32||loadouts.size()!=Role.values().length)throw new IllegalArgumentException("Неверные условия специальностей армии");}
 public static TacticsSettings defaults(){return new TacticsSettings(true,2,3600000,1800000,16,8,Map.of(
  Role.SOLDIER,new Loadout(Map.of("metal",13000L,"wood",6000L,"food",8000L),Map.of("IRON_SWORD",1,"IRON_HELMET",1,"IRON_CHESTPLATE",1,"SHIELD",1,"BREAD",8)),
  Role.SAPPER,new Loadout(Map.of("metal",4000L,"wood",2000L,"materials",20000L),Map.of("IRON_PICKAXE",1,"FLINT_AND_STEEL",1,"TNT",4)),
  Role.MEDIC,new Loadout(Map.of("knowledge",8000L,"water",4000L,"food",8000L,"materials",4000L),Map.of("SPLASH_POTION_HEALING",4,"BREAD",8)),
  Role.SUPPLIER,new Loadout(Map.of("food",32000L,"wood",8000L,"materials",8000L),Map.of("BREAD",32,"ARROW",32))));}
 public static TacticsSettings load(ConfigurationSection c){var def=defaults();var sets=new EnumMap<Role,Loadout>(Role.class);for(Role role:Role.values()){var root=c.getConfigurationSection("tactics.kits."+role.id());if(root==null){sets.put(role,def.loadouts().get(role));continue;}var costs=root.getConfigurationSection("cost");var items=root.getConfigurationSection("items");if(costs==null||items==null)throw new IllegalArgumentException("У комплекта нужны разделы cost и items");var cost=new HashMap<String,Long>();var stacks=new HashMap<String,Integer>();for(String k:costs.getKeys(false))try{long n=new BigDecimal(String.valueOf(costs.get(k))).movePointRight(3).longValueExact();if(n<1)throw new ArithmeticException();cost.put(k,n);}catch(RuntimeException error){throw new IllegalArgumentException("Неверная стоимость комплекта: "+k,error);}for(String k:items.getKeys(false))stacks.put(k,Math.toIntExact(number(items,k,0)));sets.put(role,new Loadout(cost,stacks));}return new TacticsSettings(c.getBoolean("tactics.enabled",def.enabled()),Math.toIntExact(number(c,"tactics.kits-per-24h",def.kitsPerDay())),Math.multiplyExact(number(c,"tactics.kit-cooldown-seconds",def.kitCooldown()/1000),1000),Math.multiplyExact(number(c,"tactics.order-duration-seconds",def.orderDuration()/1000),1000),decimal(c,"tactics.arrival-radius",def.arrivalRadius()),Math.toIntExact(number(c,"tactics.max-active-orders",def.activeOrders())),sets);}
 private static long number(ConfigurationSection c,String k,long fallback){Object raw=c.get(k);if(raw==null)return fallback;if(!(raw instanceof Integer||raw instanceof Long))throw new IllegalArgumentException("Нужно целое число: "+k);return ((Number)raw).longValue();}
 private static double decimal(ConfigurationSection c,String k,double fallback){Object raw=c.get(k);if(raw==null)return fallback;if(!(raw instanceof Number n)||!Double.isFinite(n.doubleValue()))throw new IllegalArgumentException("Нужно число: "+k);return n.doubleValue();}
}
